 // Helper functions
 export function getPageBySlug(slug: string, pool: PageDefinition[]): PageDefinition | undefined {
   return pool.find(p => p.slug === slug);
 }
 
 export function getRelatedPages(page: PageDefinition, pool: PageDefinition[]): PageDefinition[] {
   return page.relatedSlugs.map(slug => getPageBySlug(slug, pool)).filter((p): p is PageDefinition => p !== undefined);
 }
 
 export function getAllSlugs(pool: PageDefinition[]): string[] {
   return pool.map(p => p.slug);
 }
 
 export function buildMetaTitle(page: PageDefinition): string {
   return page.metaTitle;
 }
 
 export function buildMetaDescription(page: PageDefinition): string {
   return page.metaDescription;
 }
